import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

sheet_name = "imported Data"
if sheet_name not in wb.sheetnames:
    ws = wb.create_sheet(sheet_name)
else:
    ws = wb[sheet_name]

vws = vals[sheet_name] if sheet_name in vals.sheetnames else None

def is_blank(value):
    return value is None or (isinstance(value, str) and value.strip() == "")

def is_in_range(value):
    if isinstance(value, bool):
        return False
    if isinstance(value, (int, float)):
        return -1 <= value <= 1
    if isinstance(value, str):
        try:
            num = float(value.strip())
        except ValueError:
            return False
        return -1 <= num <= 1
    return False

kept = []
if vws is not None:
    for row in range(1, 8):
        value = vws.cell(row=row, column=3).value
        if row == 1:
            if not is_blank(value):
                kept.append(value)
        else:
            if not is_blank(value) and not is_in_range(value):
                kept.append(value)

for row in range(1, 8):
    if row <= len(kept):
        value = kept[row - 1]
        if isinstance(value, str):
            value = value.strip()
        ws.cell(row=row, column=3).value = value
    else:
        ws.cell(row=row, column=3).value = None

wb.save(OUT)

print("kept:", kept)
